posts = {"자전거": (0.10, 0.010, 0.00), "유모차": (0.06, 0.020, 0.00), "낚시글": (0.20, 0.001, 0.05)}
def value(t):
    c, ch, h = t
    return 10 * c + 100 * ch - 50 * h
for k, t in sorted(posts.items(), key=lambda kv: -value(kv[1])):
    print(f"{k}: p(클릭) {t[0]:.2f} / 가치 {value(t):.2f}")
# 유모차: p(클릭) 0.06 / 가치 2.60
# 자전거: p(클릭) 0.10 / 가치 2.00
# 낚시글: p(클릭) 0.20 / 가치 -0.40

cands = {"u1": ["a", "b", "c", "d"], "u2": ["e", "f", "g", "h"], "u3": ["i", "j", "k", "l"]}
clicked = {"u1": "c", "u2": "z", "u3": "i"}
for K in (2, 4):
    hit = sum(clicked[x] in c[:K] for x, c in cands.items())
    print(f"Recall@{K} = {hit}/{len(cands)}")
# Recall@2 = 1/3
# Recall@4 = 2/3
